// intent: Verify that parsing CBOR with an extended tag (>= 0xD8) in front of a map key using ignore tag handler successfully skips the tag and parses the map.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        std::vector<std::uint8_t> const cbor = {
            0xA1,             // map of 1 pair
            0xD8, 0x2A,       // tag 42 (extended tag format 0xD8)
            0x61, 0x61,       // key "a"
            0x01              // value 1
        };
        auto j = nlohmann::json::from_cbor(cbor, true, true, nlohmann::json::cbor_tag_handler_t::ignore);
        std::cout << j.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}
